import { useState, useEffect } from 'react';
import axios from 'axios';
import { Div, StyledLink, Li, H1 } from './Home.styled.js';

const Home = () => {
    const [movies, setMovies] = useState([]);
    const [error, setError] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchTrendingMovies = async () => {
            const API_KEY = 'b3fe8ad645f337f3fa9ceb8e5b164aa5'; // Replace with actual API key
            const url = `https://api.themoviedb.org/3/movie/top_rated?api_key=${API_KEY}`;
            
            try {
                const response = await axios.get(url);
                console.log('API Response:', response.data); // Log the response
                setMovies(response.data.results || []);
                setError(false);
            } catch (error) {
                console.error('API Error:', error.response || error.message);
                if (error.response?.status === 403) {
                    console.error('403 Forbidden: Invalid API Key or Access Denied');
                }
                setError(true);
            } finally {
                setLoading(false);
            }
        };

        fetchTrendingMovies();
    }, []);

    if (loading) return <div>Loading trending movies...</div>;
    if (error) return <div>Error fetching trending movies. Please try again later.</div>;

    return (
        <Div>
            <H1>Trending Today</H1>
            <ul>
                {movies.map(movie => (
                    <Li key={movie.id}>
                        <StyledLink to={`/movies/${movie.id}`}>
                            {movie.title || movie.name}
                        </StyledLink>
                    </Li>
                ))}
            </ul>
        </Div>
    );
};

export default Home;
